-- ============================================================================
-- B5 FOLLOW-ON W5 (section 3 pick B, strip): perfsand. The W1 open-book label
-- comes off the brief of each tier below.
--
-- WHY. W1 (D4 C) labelled these briefs open book because a lesson, a panel's
-- opening view or the page printed some graded answers. Those prints are gone
-- (NextGen zip; src/components/course/panels/perfsand/capstoneLeak.test.jsx
-- proves each tier prints none and runs a negative control), so the label is
-- no longer true.
--
-- advanced:
--   nothing printed its answers: re-measured, no lesson in any tier and no panel
--   first render prints a graded Expert value (four of the five B5 leak flags
--   came from a sentence saying the lessons print NO stress or strength numbers;
--   the gauge margin is one of seven rows of the gauge table, and picking the
--   row is the work), so the label was untrue
--
-- WHAT MOVES. The brief's first sentence (the label). The brief becomes exactly
-- its text before W1.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its live value exactly, before and after, so no answer grades
-- differently and there is no attempts guard (pick B keeps the keys).
--
-- GUARDS. Each brief must hold its W1-labelled text (md5, rewritten) or its
-- unlabelled text (left alone), with the fields this file was generated
-- against. Anything else raises and the file rolls back. The file refuses
-- unless W1 is applied. Generated by docs/graded-field-audit/w5d_capstones.py.
-- SAFE TO RE-RUN.
--
-- AFTER THIS FILE, 20261024b_w1_openbook_perfsand.sql reads these tiers as its
-- "published" form again and would put the label back: it is SUPERSEDED and
-- must not be re-applied (/root/w5d-apply/apply.sh reports it so).
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- W1 (20261024*) must be applied: before it, an unlabelled brief is not evidence of anything
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'gasprocessing' and c.tier = 'beginner' and c.active
                    and f->>'key' = 'tegReboilerMMBtuHr') then
    raise exception 'w5d perfsand refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  -- perfsand / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'perfsand' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w5d perfsand refused: perfsand/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '79d9f8e3c894368cb67c7bb5ed21b5dd' and fields = '[{"key": "gravel_band_min_m", "tol": 5E-10, "unit": "m", "label": "Gravel band minimum", "expected": 0.0007577408447368442}, {"key": "gauge_margin_m", "tol": 5E-10, "unit": "m", "label": "Gauge margin", "expected": 0.00008699999999999995}, {"key": "pwf_crit_pa", "tol": 500, "unit": "Pa", "label": "Critical flowing pressure", "expected": 11691094.102374725}, {"key": "cdp_governing_pa", "tol": 500, "unit": "Pa", "label": "Governing CDP", "expected": 8884412.847751666}, {"key": "cdp_bottom_pa", "tol": 500, "unit": "Pa", "label": "CDP at the bottom station", "expected": 12588855.56336058}, {"key": "boost_at_zero_margin", "tol": 5E-7, "unit": "", "label": "Boost at zero margin", "expected": 0.7896888993074376}]'::jsonb then 'old'
              when md5(prompt) = '62b02d599b5860369be90d007ea70718' and fields = '[{"key": "gravel_band_min_m", "tol": 5E-10, "unit": "m", "label": "Gravel band minimum", "expected": 0.0007577408447368442}, {"key": "gauge_margin_m", "tol": 5E-10, "unit": "m", "label": "Gauge margin", "expected": 0.00008699999999999995}, {"key": "pwf_crit_pa", "tol": 500, "unit": "Pa", "label": "Critical flowing pressure", "expected": 11691094.102374725}, {"key": "cdp_governing_pa", "tol": 500, "unit": "Pa", "label": "Governing CDP", "expected": 8884412.847751666}, {"key": "cdp_bottom_pa", "tol": 500, "unit": "Pa", "label": "CDP at the bottom station", "expected": 12588855.56336058}, {"key": "boost_at_zero_margin", "tol": 5E-7, "unit": "", "label": "Boost at zero margin", "expected": 0.7896888993074376}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'perfsand' and tier = 'advanced' and active;
  if v_s0 = 'other' then
    raise exception 'w5d perfsand refused: perfsand/advanced matches neither its W1-labelled form (prompt md5 79d9f8e3c894368cb67c7bb5ed21b5dd) nor its stripped form (prompt md5 62b02d599b5860369be90d007ea70718), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already stripped
  if v_s0 = 'new' then
    raise notice 'w5d perfsand: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Six values. THE SAND is the Associate capstone sieve, cumulative retained in microns: 560 at 2, 400 at 7, 280 at 19, 200 at 36, 140 at 54, 100 at 70, 70 at 83, 50 at 92 and 38 at 96. THE INTERVAL runs from 2200 to 2320 m measured depth, screened at a step of 25 m, as an OPEN HOLE cavity, with a strength boost factor of 1.15. Report: (1) the MINIMUM of the Saucier gravel band in metres; (2) the GAUGE MARGIN in metres, meaning the largest permissible gauge less the gauge actually selected; (3) the CRITICAL FLOWING PRESSURE at the governing station in pascals; (4) the GOVERNING critical drawdown pressure in pascals; (5) the critical drawdown pressure at the BOTTOM station in pascals; and (6) the boost factor at which the governing margin is exactly ZERO. Traps. The Saucier band is a multiplier on D50 and NOT on D10, and using the coarse percentile oversizes the pack by a factor of well over two. The gauge series is DISCRETE, so field 2 is a leftover and not a design choice, and it is the bound less the SELECTED gauge rather than the bound less the gravel size. The step does NOT divide the interval: 120 m at 25 m gives 2200, 2225, 2250, 2275, 2300 and then a CLAMPED bottom at 2320, which is SIX rows and not five, and the sixth exists only because the engine walks to the interval bottom rather than to the last whole step before it. Fields 4 and 5 are DIFFERENT numbers and field 4 is the SMALLER: on this interval the TOP station governs, so a learner who assumes the deepest row is the worst one reports field 5 twice. Field 6 is a search and not a formula. Free checks: field 5 must EXCEED field 4, since the governing value is a minimum over the rows; field 6 must be BELOW the applied 1.15, because at 1.15 the interval still has margin; and field 1 must equal five times the Associate tier D50 exactly.'
     where app_slug = 'perfsand' and tier = 'advanced' and active and md5(prompt) = '79d9f8e3c894368cb67c7bb5ed21b5dd';
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w5d perfsand refused: perfsand/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '62b02d599b5860369be90d007ea70718' and fields = '[{"key": "gravel_band_min_m", "tol": 5E-10, "unit": "m", "label": "Gravel band minimum", "expected": 0.0007577408447368442}, {"key": "gauge_margin_m", "tol": 5E-10, "unit": "m", "label": "Gauge margin", "expected": 0.00008699999999999995}, {"key": "pwf_crit_pa", "tol": 500, "unit": "Pa", "label": "Critical flowing pressure", "expected": 11691094.102374725}, {"key": "cdp_governing_pa", "tol": 500, "unit": "Pa", "label": "Governing CDP", "expected": 8884412.847751666}, {"key": "cdp_bottom_pa", "tol": 500, "unit": "Pa", "label": "CDP at the bottom station", "expected": 12588855.56336058}, {"key": "boost_at_zero_margin", "tol": 5E-7, "unit": "", "label": "Boost at zero margin", "expected": 0.7896888993074376}]'::jsonb) from public.academy_capstones where app_slug = 'perfsand' and tier = 'advanced' and active) is not true then
    raise exception 'w5d perfsand refused: perfsand/advanced does not read back as its stripped form';
  end if;

  raise notice 'w5d perfsand: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
